#include <iostream>
#include <string>
#include <algorithm>

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    std::string arr, brr;
    std::cin >> arr >> brr;

    int ans = 0;
    int n = arr.length();

    for (int i = 0; i < n; i++) {
        for (int j = i; j < n; j++) {
            int count = 0;
            for (int k = 0; k < n; k++) {
                if (k < i || k > j) {
                    if (count < brr.length()) {
                        if (arr[k] == brr[count]) {
                            count++;
                        }
                    } else {
                        break;
                    }
                }
            }
            if (count == brr.length()) {
                ans = std::max(ans, j - i + 1);
            }
        }
    }

    std::cout << ans << std::endl;

    return 0;
}

